The resume path, actually reading the checkpoint:

```js
async function resumeOrStart(runId, initialState) {
  const cp = await db.query(
    `SELECT step, state FROM run_checkpoints WHERE run_id = $1`,
    [runId],
  );
  if (cp.rows.length === 0) {
    return { step: 0, state: initialState }; // genuinely new run, nothing to resume
  }
  const { step, state } = cp.rows[0];
  return { step, state: JSON.parse(state) }; // pick up exactly where the checkpoint left off
}

async function run(runId, steps, initialState) {
  let { step, state } = await resumeOrStart(runId, initialState);
  while (step < steps.length) {
    state = await runStep(runId, step, steps[step], state);
    step += 1;
  }
  return state;
}
```

`run` is now the same function whether it's a fresh start or a resume after a crash — the branch happens once, inside `resumeOrStart`, instead of needing two different entry points that have to be kept in sync by hand.

